script:
if doc.custom_cira_authority_signature and doc.custom_cira_authority_acknowledged and not doc.custom_cira_authority_pdf:
    try:
        attached = frappe.attach_print("Loan Application", doc.name, file_name="CIRA Authority - %s" % doc.name, print_format="CIRA Authority Form", doc=doc)
        frappe.db.set_value("Loan Application", doc.name, "custom_cira_authority_pdf", attached.file_url, update_modified=False)
    except Exception:
        if ".localhost" not in frappe.get_url():
            raise

if not doc.mode_of_payment and doc.against_loan:
    loan_application = frappe.db.get_value("Loan", doc.against_loan, "loan_application")
    agreed_method = frappe.db.get_value("Loan Application", loan_application, "custom_flexi_payment_method") if loan_application else None
    payment_modes = {
        "Bank - PPT": "Bank PPT",
        "Payroll Deduction": "Payroll Deduction",
        "Cash / Direct Payment": "Cash",
        "Other": "Other",
    }
    if agreed_method in payment_modes:
        doc.mode_of_payment = payment_modes[agreed_method]

if not doc.mode_of_payment and doc.against_loan:
    disbursements = frappe.get_all(
        "Loan Disbursement",
        filters={"against_loan": doc.against_loan, "docstatus": 1},
        fields=["mode_of_payment"],
        order_by="creation desc",
        limit_page_length=1
    )
    if disbursements and disbursements[0].get("mode_of_payment"):
        doc.mode_of_payment = disbursements[0].get("mode_of_payment")
    else:
        loan_application = frappe.db.get_value("Loan", doc.against_loan, "loan_application")
        agreed_method = frappe.db.get_value("Loan Application", loan_application, "custom_flexi_payment_method") if loan_application else None
        payment_modes = {
            "Bank - PPT": "Bank PPT",
            "Payroll Deduction": "Payroll Deduction",
            "Cash / Direct Payment": "Cash",
            "Other": "Other",
        }
        if agreed_method in payment_modes:
            doc.mode_of_payment = payment_modes[agreed_method]

for row in doc.get("documents") or []:
    if not row.file:
        continue

    files = frappe.get_all(
        "File",
        filters={"file_url": row.file},
        fields=["name", "attached_to_doctype", "attached_to_name"],
    )

    if not files:
        frappe.get_doc({
            "doctype": "File",
            "file_url": row.file,
            "is_private": 1 if row.file.startswith("/private/") else 0,
            "attached_to_doctype": doc.doctype,
            "attached_to_name": doc.name,
        }).insert(ignore_permissions=True)
        continue

    for f in files:
        if f.attached_to_name:
            continue
        frappe.db.set_value("File", f.name, {
            "attached_to_doctype": doc.doctype,
            "attached_to_name": doc.name,
        }, update_modified=False)

for row in doc.get("documents") or []:
    if not row.file:
        continue

    files = frappe.get_all(
        "File",
        filters={"file_url": row.file},
        fields=["name", "attached_to_doctype", "attached_to_name"],
    )

    if not files:
        frappe.get_doc({
            "doctype": "File",
            "file_url": row.file,
            "is_private": 1 if row.file.startswith("/private/") else 0,
            "attached_to_doctype": doc.doctype,
            "attached_to_name": doc.name,
        }).insert(ignore_permissions=True)
        continue

    for f in files:
        if f.attached_to_name:
            continue
        frappe.db.set_value("File", f.name, {
            "attached_to_doctype": doc.doctype,
            "attached_to_name": doc.name,
        }, update_modified=False)

templates = frappe.get_all(
    "Loan Document Template",
    filters={"status": "Current", "document_code": ("!=", "REQ")},
    fields=["name", "document_code", "version", "sequence"],
    order_by="sequence asc"
)

existing_templates = []
for row in (doc.custom_customer_documents or []):
    if row.document_template:
        existing_templates.append(row.document_template)
        if not row.document_code:
            row.document_code = frappe.db.get_value(
                "Loan Document Template", row.document_template, "document_code"
            )

for template in templates:
    if template.name not in existing_templates:
        row = doc.append("custom_customer_documents", {})
        row.document_template = template.name
        row.document_code = template.document_code
        row.version = template.version or 1
        row.status = "Pending"

if not doc.custom_flexi_hp_account_number and not doc.is_new():
    doc.custom_flexi_hp_account_number = doc.name
